/**
 * Skill Template Workflow Modules
 *
 * This file is generated by splitting the legacy monolithic
 * templates file into workflow-focused modules.
 */
import type { SkillTemplate, CommandTemplate } from '../types.js';
import { optionalWorkflow } from '../optional-workflow.js';
import { STORE_SELECTION_GUIDANCE } from './store-selection.js';
import { PROJECT_ROOT_GUARD } from './project-root.js';

/**
 * The planning-complete handoff. Neither `apply` nor `archive` is guaranteed
 * to be installed, so each half is resolved at generation time (see
 * optional-workflow.ts).
 */
const PLANNING_COMPLETE_HANDOFF = optionalWorkflow(
  'apply',
  '现在可以用 `/opsx:apply` 实现这个变更。',
  '现在可以实现这个变更 —— `openspec-cn instructions apply --change "<name>" --json` 会返回任务列表以及如何执行它们。'
) + ' ' + optionalWorkflow(
  'archive',
  '当实现以及所有被追踪的工作都完成后，用 `/opsx:archive` 归档它。',
  '当实现以及所有被追踪的工作都完成后，用 `openspec-cn archive "<name>"` 归档它。'
);

/**
 * A glob artifact reads `done` once one matching file exists, so a run
 * interrupted while writing several files leaves it `done` with files missing,
 * and the next run would move on without reading its instruction again (#2034).
 */
const PARTIAL_ARTIFACT_CHECK = `**首先，完成一个只写了一部分的产出物**：
   - 输出为 glob 模式（例如 \`specs/**/*.md\`）的制品，只要存在一个匹配文件就会读取为 \`done\`，因此一次在写入多个文件时被中断的运行会让它保持 \`done\` 但仍缺少部分文件
   - 对每个此类 \`done\` 制品，先获取其指令并读取任何已完成的依赖，以确定预期的文件。然后将这些文件与 \`artifactPaths.<id>.existingOutputPaths\` 比较。对 spec-driven 的 \`specs\`，阅读 proposal 并检查它列出的每个能力是否都有一个 \`specs/<capability-path>/spec.md\`；比较路径同一性前先将每个预期路径对 \`changeRoot\` 解析，并验证每个路径在解析符号链接后仍位于 \`changeRoot\` 之内 —— 无论是其父目录，还是文件本身（若它已存在）
   - 绝不要写入未通过该检查的预期路径；此时应停止并告知用户。若有缺失，只写入缺失的文件，每个都写到其已检查的路径上 —— 当 \`instruction\` 字段将创建委托给 skill 或命令时，仅当它能把每个文件写入其已检查的路径时才调用它；否则停止并告知用户 —— 然后停止 —— 这算作本次调用的唯一一个制品。若无法判断某个文件是否是有意省略的，请询问用户`;

export function getContinueChangeSkillTemplate(): SkillTemplate {
  return {
    name: 'openspec-continue-change',
    description: '通过创建下一个产出物来继续处理 OpenSpec 变更。当用户想推进变更、创建下一个产出物或继续工作流时使用。也在用户说 "openspec continue" 或 "opsx continue" 时使用。',
    instructions: `通过创建下一个产出物来继续处理变更。

${STORE_SELECTION_GUIDANCE}

${PROJECT_ROOT_GUARD}

**Input**: 可选地指定变更名。若省略，检查能否从对话上下文推断。若模糊或歧义，你必须提示用户从可用变更中选择。

**步骤**

1. **选择变更**

   若提供了名称，使用它。否则：
   - 从对话上下文推断（若用户提到了某个变更）
   - 若仅有一个活跃变更则自动选择
   - 若存在歧义，运行 \`openspec-cn list --json\` 获取按最近修改排序的可用变更，并让用户选择

   提示时，展示最近修改的前 3-4 个变更作为选项，显示：
   - 变更名称
   - 状态（例如 "0/5 tasks"、"complete"、"no tasks"）
   - 最近修改时间（来自 \`lastModified\` 字段）

   将最近修改的变更标记为 "(推荐)"，因为这很可能是用户想继续的。

   始终宣告："使用变更：<name>"，以及如何覆盖（例如 \`/opsx:continue <other>\`）。

2. **检查当前状态**
   \`\`\`bash
   openspec-cn status --change "<name>" --json
   \`\`\`
   解析 JSON 以理解当前状态。响应包括：
   - \`schemaName\`：使用的工作流 schema（例如 "spec-driven"）
   - \`artifacts\`：制品数组及其状态（"done"、"skipped"、"ready"、"blocked"）
   - \`isPlanningComplete\`：布尔值，表示所有规划制品是否已完成。较旧 CLI 版本以 \`isComplete\` 暴露相同值。
   - \`planningHome\`、\`changeRoot\`、\`artifactPaths\` 和 \`actionContext\`：路径和作用域上下文。请使用这些值而非假设仓库本地路径。

3. **基于状态行动**：

   ---

   ${PARTIAL_ARTIFACT_CHECK}

   ---

   **若所有规划制品已完成（\`isPlanningComplete: true\`，或旧版 \`isComplete: true\`）**：
   - 祝贺用户
   - 展示最终状态，包括使用的 schema
   - 建议："规划完成！现在可以实现此变更。实现及所有跟踪的工作完成后，归档它。"
   - 停止

   ---

   **若产出物已就绪可创建**（状态显示有 \`status: "ready"\` 的产出物）：
   - 从状态输出中选取第一个 \`status: "ready"\` 的产出物
   - 获取其指令：
     \`\`\`bash
     openspec-cn instructions <artifact-id> --change "<name>" --json
     \`\`\`
   - 解析 JSON。关键字段：
     - \`context\`：项目背景（给你的约束 - 不要包含在输出中）
     - \`rules\`：产出物特定规则（给你的约束 - 不要包含在输出中）
     - \`template\`：输出文件使用的结构
     - \`instruction\`：schema 特定指导
     - \`resolvedOutputPath\`：写入产出物的已解析路径或模式
     - \`dependencies\`：已完成的需要读取以获取上下文的产出物（带有 \`skipped: true\` 的条目无文件 - 不要查找它们）
     - \`skipped\`/\`warning\`：当变更声明 skip_specs 且此产出物必须不创建时出现 - 选择另一个产出物
   - **创建产出物文件**：
     - 读取所有已完成的依赖文件以获取上下文 - 始终从磁盘重新读取，即使在对话中之前已看到（用户可能已编辑过）
     - 先选定输出路径，再创建任何内容。若指令中指定的 \`resolvedOutputPath\` 是 glob 模式，则根据 schema 指令和变更的上下文在 \`changeRoot\` 内选择具体路径，并验证它在解析符号链接后仍位于 \`changeRoot\` 之内 —— 无论是其父目录，还是文件本身（若它已存在）；若不是，停止并告知用户。否则输出路径就是 \`resolvedOutputPath\`
     - 若 \`instruction\` 字段将创建委托给特定 skill 或命令，则仅当它能把产出物写入该输出路径时才调用它；否则停止并告知用户
     - 否则由你自己写入：
       - 使用 \`template\` 作为结构 - 填写其各节
       - 写入时将 \`context\` 和 \`rules\` 作为约束应用 - 但不要将它们复制到文件中
       - 将文件写入该输出路径
     - 无论走哪条路径，都要验证产出物文件存在于该输出路径
   - 展示已创建的内容以及现在解锁了什么
   - 每次仅创建一个产出物，创建后即停止

   ---

   **若没有产出物就绪（全部受阻）**：
   - 这在有效 schema 中不应发生
   - 展示状态并建议检查问题

4. **创建产出物后，展示进度**
   \`\`\`bash
   openspec-cn status --change "<name>"
   \`\`\`

**输出**

每次调用后，展示：
- 创建了哪个产出物
- 使用的 schema 工作流
- 当前进度（N/M 已完成）
- 现在解锁了哪些产出物
- 提示："想继续吗？只要让我继续或告诉我接下来做什么。"

**产出物创建指南**

产出物类型及其用途取决于 schema。指令输出中的 \`instruction\` 字段是每个产出物的权威指导 — 即使产出物名称熟悉（proposal.md、tasks.md 等）也应遵循它，因为自定义 schema 可能为相同文件名定义不同内容或不同流程。

若 \`instruction\` 字段指示你使用特定 skill 或命令创建产出物，则调用它而非直接写入产出物 —— 但仅在已选定并检查过输出路径之后，且仅当它能写入该处时才调用。

**护栏**
- 每次调用仅创建一个产出物
- 始终在创建新产出物之前读取依赖产出物 - 从磁盘重新读取，而非对话记忆（文件可能自你上次看到后已变更）
- 绝不跳过产出物或乱序创建
- 若上下文不清，创建前先询问用户
- 在标记进度之前，先验证写入后产出物文件确实存在
- 使用 schema 的产出物顺序，不要假设特定的产出物名称
- **重要提示**：\`context\` 和 \`rules\` 是给你的约束，不是文件内容
  - 不要将 \`<context>\`、\`<rules>\`、\`<project_context>\` 块复制到产出物中
  - 这些指导你写什么，但绝不应出现在输出中`,
    license: 'MIT',
    compatibility: '需要 openspec-cn CLI。',
    metadata: { author: 'openspec', version: '1.0' },
  };
}

